void BinderBinderItemsListModel::onBinderItemCreated(const QList<int> &ids)
{
    if (!m_binderController || !m_binderItemController || m_binderId <= 0)
        return;

    // Fetch the binder's current event relationship to find which created
    // binderItems belong to us (e.g. after undo-delete restores the junction row).
    QCoro::Task<QList<int>> relTask =
        m_binderController->getRelationshipIds(m_binderId, BinderRelationshipField::BinderItems);

    QCoro::connect(std::move(relTask), this, [this, ids](auto &&relatedIds) {
        if (!m_binderItemController)
            return;

        // Build set of IDs already in the model
        QSet<int> currentIds;
        for (const auto &item : m_binderItems)
            currentIds.insert(item.id);

        // Find which created IDs belong to this binder and are not yet in the model
        QList<int> addedIds;
        for (const int id : ids)
        {
            if (relatedIds.contains(id) && !currentIds.contains(id))
                addedIds.append(id);
        }

        if (addedIds.isEmpty())
            return;

        QCoro::Task<QList<BinderItem::BinderItemDto>> fetchTask = m_binderItemController->get(addedIds);

        QCoro::connect(std::move(fetchTask), this, [this, relatedIds](auto &&fetchResult) {
            if (!m_binderItemController || fetchResult.isEmpty())
                return;

            // Build a lookup from id to fetched dto
            QHash<int, BinderItem::BinderItemDto> fetchedById;
            for (const BinderItem::BinderItemDto &dto : fetchResult)
            {
                if (dto.activated)
                    fetchedById.insert(dto.id, dto);
            }

            // Insert each new item at its correct position according to relatedIds ordering
            for (int targetPos = 0; targetPos < relatedIds.size(); ++targetPos)
            {
                const int id = relatedIds[targetPos];
                if (!fetchedById.contains(id))
                    continue;

                const int insertPos = qMin(targetPos, m_binderItems.size());
                beginInsertRows(QModelIndex(), insertPos, insertPos);
                m_binderItems.insert(insertPos, fetchedById.value(id));
                endInsertRows();
            }

            // Fix ordering after insertions since existing items may not be at target positions
            reorderToMatch(relatedIds);
        });
    });
}

