        return;
    if (relationshipField != Common::DirectAccess::Binder::BinderRelationshipField::BinderItems)
        return;

    // Mark as handled so the subsequent updated signal skips duplicate processing
    m_lastRelationshipChangeHandled = true;

    // Build set of current IDs
    QSet<int> currentIds;
    for (const auto &item : m_binderItems)
    {
        currentIds.insert(item.id);
    }

    QSet<int> newIds(relatedIds.begin(), relatedIds.end());

    // Find removed IDs and remove them from the model
    QSet<int> removedIds = currentIds - newIds;
    for (const int id : removedIds)
    {
        for (int i = 0; i < m_binderItems.size(); ++i)
        {
            if (m_binderItems[i].id == id)
            {
                beginRemoveRows(QModelIndex(), i, i);
                m_binderItems.removeAt(i);
                endRemoveRows();
                break;
            }
        }
    }

    // Find added IDs and fetch them
    QList<int> addedIds;
    for (const int id : relatedIds)
    {
        if (!currentIds.contains(id))
        {
            addedIds.append(id);
        }
    }

    // If no additions, just reorder existing items to match relatedIds ordering
    if (addedIds.isEmpty())
    {
        reorderToMatch(relatedIds);
        return;
    }

    if (!m_binderItemController)
        return;

    QCoro::Task<QList<BinderItem::BinderItemDto>> fetchTask = m_binderItemController->get(addedIds);

    QCoro::connect(std::move(fetchTask), this, [this, relatedIds](auto &&result) {
        if (!m_binderItemController)
            return;

        if (result.isEmpty())
            return;

        // Build a lookup from id to fetched dto
        QHash<int, BinderItem::BinderItemDto> fetchedById;
        for (const BinderItem::BinderItemDto &dto : result)
        {
            fetchedById.insert(dto.id, dto);
        }

        // Insert each new item at its correct position according to relatedIds ordering
        for (int targetPos = 0; targetPos < relatedIds.size(); ++targetPos)
        {
            const int id = relatedIds[targetPos];
            if (!fetchedById.contains(id))
                continue;

            // targetPos may exceed current size if items are at the end
            const int insertPos = qMin(targetPos, m_binderItems.size());
            beginInsertRows(QModelIndex(), insertPos, insertPos);
            m_binderItems.insert(insertPos, fetchedById.value(id));
            endInsertRows();
        }

        // Fix ordering after insertions since existing items may not be at target positions
        reorderToMatch(relatedIds);
    });
