void BinderBinderItemsListModel::reorderToMatch(const QList<int> &orderedIds)
{
    // Build a map from id to desired position
    QHash<int, int> idToDesiredPos;
    for (int i = 0; i < orderedIds.size(); ++i)
    {
        idToDesiredPos.insert(orderedIds[i], i);
    }

    // Move items into their correct positions
    for (int desiredPos = 0; desiredPos < m_binderItems.size(); ++desiredPos)
    {
        // Find which item should be at desiredPos
        int currentId = m_binderItems[desiredPos].id;
        if (idToDesiredPos.value(currentId, desiredPos) == desiredPos)
            continue;

        // Find the item that belongs at desiredPos
        int sourcePos = -1;
        for (int j = desiredPos + 1; j < m_binderItems.size(); ++j)
        {
            if (idToDesiredPos.value(m_binderItems[j].id, j) == desiredPos)
            {
                sourcePos = j;
                break;
            }
        }

        if (sourcePos < 0)
            continue;

        beginMoveRows(QModelIndex(), sourcePos, sourcePos, QModelIndex(), desiredPos);
        m_binderItems.move(sourcePos, desiredPos);
        endMoveRows();
    }
}

